    ListAccountsError,
    ListAccountsResponse,
    ReturnType<typeof listAccountsQueryKey>
  >({
    queryFn: async ({ queryKey, signal }) => {
      const { data } = await listAccounts({
        ...options,
        ...queryKey[0],
        signal,
        throwOnError: true,
      });
      return data;
    },
    queryKey: listAccountsQueryKey(options),
  });

const createInfiniteParams = <
  K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>,
>(
  queryKey: QueryKey<Options>,
  page: K,
) => {
  const params = { ...queryKey[0] };
  if (page.body) {
    params.body = {
      ...(queryKey[0].body as any),
      ...(page.body as any),
    };
  }
  if (page.headers) {
    params.headers = {
      ...queryKey[0].headers,
      ...page.headers,
    };
  }
  if (page.path) {
    params.path = {
      ...(queryKey[0].path as any),
      ...(page.path as any),
    };
  }
  if (page.query) {
    params.query = {
      ...(queryKey[0].query as any),
      ...(page.query as any),
    };
  }
  return params as unknown as typeof page;
};

export const listAccountsInfiniteQueryKey = (
  options?: Options<ListAccountsData>,
): QueryKey<Options<ListAccountsData>> => createQueryKey('listAccounts', options, true);

/**
 * List Accounts
 *
 * One page of accounts; ``total`` counts every account the filters match.
 *
 * ``status``: ``all``, a stat-tile bucket (``active`` / ``idle`` / ``needs_code`` /
 * ``problem``) or one raw account status. ``folder``: a folder id or ``unfiled``.
 * ``phone_code``: a calling code (``7``). ``proxy_country``: ISO alpha-2 or ``none``.
 */
export const listAccountsInfiniteOptions = (options?: Options<ListAccountsData>) => {
  const opts = infiniteQueryOptions<
    ListAccountsResponse,
    ListAccountsError,
    InfiniteData<ListAccountsResponse>,
    QueryKey<Options<ListAccountsData>>,
    | string
    | null
    | Pick<QueryKey<Options<ListAccountsData>>[0], 'body' | 'headers' | 'path' | 'query'>
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<ListAccountsData>>[0],
          'body' | 'headers' | 'path' | 'query'
        > =
          typeof pageParam === 'object'
            ? pageParam
            : {
                query: {
                  cursor: pageParam,
                },
              };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await listAccounts({
          ...options,
          ...params,
          signal,
          throwOnError: true,
        });
        return data;
      },
      queryKey: listAccountsInfiniteQueryKey(options),
    },
  );
  return opts as Omit<typeof opts, 'initialData'>;
};

